import { chromium } from 'playwright';
import fs from 'node:fs';
import assert from 'node:assert/strict';
const URL='https://basspauloandres-svg.github.io/hooklab-time/producer-interface-v0.5/';
const wav='/tmp/hooklab-click120.wav';
function writeClick(path){const sr=22050,seconds=4,n=sr*seconds,b=Buffer.alloc(44+n*2);b.write('RIFF',0);b.writeUInt32LE(36+n*2,4);b.write('WAVE',8);b.write('fmt ',12);b.writeUInt32LE(16,16);b.writeUInt16LE(1,20);b.writeUInt16LE(1,22);b.writeUInt32LE(sr,24);b.writeUInt32LE(sr*2,28);b.writeUInt16LE(2,32);b.writeUInt16LE(16,34);b.write('data',36);b.writeUInt32LE(n*2,40);for(let i=0;i<n;i++){const phase=i%(sr/2),v=phase<500?Math.round(16000*Math.sin(2*Math.PI*1000*phase/sr)*Math.exp(-phase/100)):0;b.writeInt16LE(v,44+i*2)}fs.writeFileSync(path,b)}
writeClick(wav);
const browser=await chromium.launch({headless:true,args:['--autoplay-policy=no-user-gesture-required']});const page=await browser.newPage({acceptDownloads:true});page.on('console',m=>console.log('BROWSER',m.type(),m.text()));page.on('requestfailed',r=>console.log('REQUEST_FAILED',r.url(),r.failure()?.errorText));page.setDefaultTimeout(150000);let ok=false;for(let i=0;i<15;i++){try{await page.goto(URL,{waitUntil:'domcontentloaded',timeout:20000});if(/v0\.5/.test(await page.title())){ok=true;break}}catch{}await new Promise(r=>setTimeout(r,4000))}assert(ok,'v0.5 route unavailable');
await page.locator('#ref').setInputFiles({name:'click120.wav',mimeType:'audio/wav',buffer:fs.readFileSync(wav)});await page.waitForFunction(()=>document.querySelector('#refState')?.textContent?.includes('AUDIT_LOCAL_REFERENCE'));await page.locator('#analyzeRef').click();await page.waitForFunction(()=>/ANALYSIS (PASS|FAIL)/.test(document.querySelector('#analysisState')?.textContent||''),null,{timeout:150000});const label=await page.locator('#analysisState').innerText();if(!/ANALYSIS PASS/.test(label))throw new Error(label);const a=await page.evaluate(()=>state.aesthetic_reference_analysis);assert.equal(a.analysis_mode,'LOCAL_ON_DEVICE_ONNX');assert.equal(a.source_audio_persistence,'NONE');assert.equal(a.scientific_ingestion,false);assert.equal(a.gate_a_ingestion,false);assert.equal(a.model_source_commit,'089b509247e6fdcec666511c0dcf0d5f39c21e73');assert(a.beat_count>1,'expected beats');assert(a.tempo_bpm_median>80&&a.tempo_bpm_median<160,'tempo outside control range: '+a.tempo_bpm_median);
await page.locator('#midiBtn').click();assert.match(await page.locator('#buildState').innerText(),/D0 LISTO/);const d=await page.evaluate(()=>state.d0_generation);assert.equal(d.stimulus_class,'D0_EXPLORATORY');assert.equal(d.scientific_d,'BLOCKED');await page.locator('#save').click();const saved=await page.evaluate(()=>JSON.parse(localStorage.getItem('hooklab_session_'+state.session_id)));assert.equal(saved.aesthetic_reference_analysis.analysis_mode,'LOCAL_ON_DEVICE_ONNX');await browser.close();console.log(JSON.stringify({status:'PASS',bpm:a.tempo_bpm_median,beats:a.beat_count,downbeats:a.downbeat_count,latency_ms:a.latency_ms},null,2));